//! Open/save round-trip through the command surface (`file.open`,
//! `cell.set`, `file.save`, `file.saveAs`), plus a black-box `TuiDriver`
//! check that a real file opens all the way through to the painted grid.
//!
//! `examples/sample.xlsx` (used here and by the demo) is generated by the
//! engine itself — see `regenerate_sample_workbook` below — never
//! hand-crafted.

use quadraui::tui::testing::TuiDriver;

use quadracalc_core::CalcApp;

/// `examples/sample.xlsx`, a sibling of the workspace root.
fn fixture_path() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../examples/sample.xlsx")
}

/// A path under the OS temp dir this process (and this test alone) owns,
/// so parallel test runs never collide on the same file.
fn scratch_path(label: &str) -> std::path::PathBuf {
    std::env::temp_dir().join(format!(
        "quadracalc-{label}-{}-{:?}.xlsx",
        std::process::id(),
        std::thread::current().id()
    ))
}

/// Regenerates `examples/sample.xlsx` from `CalcApp::with_sample()` through
/// `file.saveAs` — the engine's own command surface, not a hand-built
/// binary file. Not run by default (nothing but this file's own tests
/// should ever need it); run it explicitly after changing the sample data:
/// `cargo test -p quadracalc-core --test open_save -- --ignored regenerate_sample_workbook`
#[test]
#[ignore = "regenerates the examples/sample.xlsx fixture; run explicitly"]
fn regenerate_sample_workbook() {
    let mut app = CalcApp::with_sample().expect("sample workbook");
    app.save_as(
        fixture_path()
            .to_str()
            .expect("fixture path is valid UTF-8"),
    )
    .expect("file.saveAs");
}

#[test]
fn fixture_exists_and_opens_through_file_open() {
    let path = fixture_path();
    assert!(
        path.exists(),
        "{} is missing — run `cargo test -p quadracalc-core --test open_save -- --ignored regenerate_sample_workbook`",
        path.display()
    );

    let mut app = CalcApp::new();
    app.open_path(path.to_str().unwrap()).expect("file.open");
    assert_eq!(app.cell_text("A1"), "Item");
    assert_eq!(app.cell_text("A2"), "Hosting");
    assert_eq!(app.cell_input("B4"), "=SUM(B2:B3)");
}

#[test]
fn open_edit_save_reopen_round_trips_through_the_command_surface() {
    let path = fixture_path();
    let scratch = scratch_path("round-trip");

    // Open the shipped sample, exactly as `quadracalc <path>` would.
    let mut app = CalcApp::new();
    app.open_path(path.to_str().unwrap()).expect("file.open");
    assert!(!app.is_dirty(), "a freshly opened workbook starts clean");

    // Edit through the one path the app ever changes a workbook: `cell.set`.
    app.set_cell("A3", "Backups").unwrap();
    assert!(app.is_dirty(), "cell.set should mark the workbook dirty");

    // Save to a scratch copy — never overwrite the checked-in fixture.
    app.save_as(scratch.to_str().unwrap()).expect("file.saveAs");
    assert!(!app.is_dirty(), "file.saveAs should clear the dirty marker");

    // A plain `file.save` after `saveAs` now has a path to write to.
    app.set_cell("A3", "Backups & restores").unwrap();
    app.save().expect("file.save");
    assert!(!app.is_dirty());

    // Reopen the scratch copy in a fresh session and see the edit stuck.
    let mut reopened = CalcApp::new();
    reopened
        .open_path(scratch.to_str().unwrap())
        .expect("file.open");
    assert_eq!(reopened.cell_text("A3"), "Backups & restores");
    assert_eq!(reopened.cell_text("A1"), "Item", "untouched cells survive");
    assert!(
        !reopened.is_dirty(),
        "a freshly opened workbook starts clean"
    );

    let _ = std::fs::remove_file(&scratch);
}

#[test]
fn opening_a_missing_file_reports_an_error_and_never_panics() {
    let app = CalcApp::new_for_path(Some("/no/such/workbook-quadracalc-test.xlsx")).unwrap();
    // `new_for_path` never propagates the open failure as `Err` — it
    // lands in the app's own error state for the status bar to show.
    assert!(!app.is_dirty());
    // The sheet stays usable (a blank workbook) rather than refusing to
    // start: `cell.set` on it must not panic either.
    let mut app = app;
    app.set_cell("A1", "still works").unwrap();
}

#[test]
fn opening_with_no_argument_keeps_the_sample_sheet() {
    let mut app = CalcApp::new_for_path(None).unwrap();
    assert_eq!(app.cell_text("A1"), "Item");
    assert_eq!(app.cell_input("B4"), "=SUM(B2:B3)");
}

#[test]
fn tui_driver_launches_on_the_sample_file_and_shows_a_known_cell() {
    let path = fixture_path();
    assert!(
        path.exists(),
        "{} is missing — run `cargo test -p quadracalc-core --test open_save -- --ignored regenerate_sample_workbook`",
        path.display()
    );
    let app = CalcApp::new_for_path(Some(path.to_str().unwrap())).unwrap();
    let driver: TuiDriver<CalcApp> = TuiDriver::new(app, 80, 20);

    // A known cell value from the sample sheet, read back from the file
    // rather than from memory — proves `file.open` fed the real grid,
    // not just that `with_sample()` ran.
    assert!(driver.screen_contains("Hosting"), "{}", driver.screen());
    assert!(driver.screen_contains("Domains"), "{}", driver.screen());
}
